 206: /** Whether two decoded events carry identical content at one seq. */
 207: function sameEvent(left, right) {
 208:     return JSON.stringify(left) === JSON.stringify(right);
 209: }
 210: /**
 211:  * Compare two candidate logs of one session by the append-only contract.
 212:  * @param local - this machine's decoded log.
 213:  * @param remote - the repo artifact's decoded log.
 214:  * @returns their relation.
 215:  */
 216: export function compareLogs(local, remote) {
 217:     const shared = Math.min(local.length, remote.length);
 218:     for (let index = 0; index < shared; index++) {
 219:         const left = local[index];
 220:         const right = remote[index];
 221:         /* v8 ignore next -- the loop indexes below both lengths */
 222:         if (left === undefined || right === undefined)
 223:             break;
 224:         if (!sameEvent(left, right))
 225:             return 'divergent';
 226:     }
 227:     if (local.length === remote.length)
 228:         return 'equal';
 229:     return local.length > remote.length ? 'remote-prefix' : 'local-prefix';
 230: }
 231: /** Error message from any thrown value. */
 232: function messageOf(error) {
 233:     return error instanceof Error ? error.message : String(error);
 234: }
 235: /** Whether two directory spellings canonicalize to the same directory. */
 236: async function samePath(left, right) {
 237:     try {
 238:         return await realpath(left) === await realpath(right);
 239:     }
 240:     catch {
 241:         // A path that does not exist on this machine can only match by spelling.
 242:         return left === right;
 243:     }
 244: }
 245: /**
 246:  * This machine's most recent session title, folded from its own log. The
 247:  * harness stores titles as `session/title` events rather than header fields,
 248:  * so a selection entry's display title is derived here (structurally, without
 249:  * importing the title package). Subagent sessions and sessions that were never
 250:  * titled simply carry no title.
 251:  * @param events - the session's logical log.
 252:  * @returns the latest title text, or an empty string when the log carries none.
 253:  */
 254: export function foldTitle(events) {
 255:     for (let index = events.length - 1; index >= 0; index--) {
 256:         const event = events[index];
 257:         if (event === undefined || event.type !== 'session/title')
 258:             continue;
 259:         const data = event.data;
 260:         if (data !== undefined && typeof data.title === 'string')
 261:             return data.title;
 262:     }
 263:     return '';
 264: }

