 379: /**
 380:  * Import one repo artifact into this machine, applying the conflict policy.
 381:  * The artifact's header `cwd` is stamped with the matched local workspace's
 382:  * path, which is what lets the harness attach the session to it.
 383:  * @param deps - services, settings, filesystem, and git surfaces.
 384:  * @param key - repo key owning the artifact.
 385:  * @param workspace - the local workspace its manifest name matched.
 386:  * @param id - the artifact's session id.
 387:  * @param result - the cycle outcome.
 388:  * @param recordConflict - conflict-path collector.
 389:  * @returns whether the artifact was actually imported (created or extended).
 390:  */
 391: async function importSession(deps, key, workspace, id, result, recordConflict) {
 392:     const repoPath = sessionRepoPath(key, id);
 393:     const remoteText = await deps.fs.readRepoFile(repoPath);
 394:     if (remoteText === undefined)
 395:         return false;
 396:     let portable;
 397:     try {
 398:         portable = parsePortableSession(remoteText, workspace.path);
 399:     }
 400:     catch (error) {
 401:         result.errors.push(`${key}/${String(id)}: ${messageOf(error)}`);
 402:         deps.logger.warn(`session sync: skipping unparsable artifact ${key}/${String(id)}: ${messageOf(error)}`);
 403:         return false;
 404:     }
 405:     // Open-turn guard: an artifact ending mid-turn is a stale snapshot an older
 406:     // plugin exported from a live session. Importing it would leave this
 407:     // machine with a log the harness repairs on load (synthetic interrupted
 408:     // closers), diverging it from the real continuation 鈥?the exact corruption
 409:     // this policy prevents. Skip until the owning machine publishes its closed
 410:     // log; meanwhile this machine's own closed log, when longer, still heals
 411:     // the artifact on export.
 412:     if (interruptedTurnClosers(portable.events).length > 0) {
 413:         result.errors.push(`${key}/${String(id)}: artifact ends mid-turn; skipping until the owning machine publishes a closed log`);
 414:         deps.logger.warn(`session sync: skipping mid-turn artifact ${key}/${String(id)}`);
 415:         return false;
 416:     }
 417:     const now = (deps.now?.() ?? new Date()).toISOString();
 418:     const host = deps.fs.hostname;
 419:     const local = await deps.persistence.inspect(id);
 420:     if (local === undefined) {
