 424:         result.imported += 1;
 425:         recordSwitchImport(result, portable, id);
 426:         await recordTransfer(deps, key, id, {
 427:             host, at: now, direction: 'pull', events: portable.events.length, result: 'ok',
 428:         }, result);
 429:         return true;
 430:     }
 431:     const localEvents = local.events;
 432:     const relation = compareLogs(localEvents, portable.events);
 433:     if (relation === 'divergent') {
 434:         const conflictPath = conflictRepoPath(key, id, deps.fs.hostname);
 435:         await deps.fs.writeRepoFile(conflictPath, remoteText);
 436:         recordConflict(conflictPath);
 437:         deps.logger.warn(`session sync: divergent logs for ${key}/${String(id)} preserved at ${conflictPath}`);
