 442:     }
 443:     if (relation === 'local-prefix') {
 444:         const appended = portable.events.slice(localEvents.length);
 445:         await deps.persistence.append(id, appended);
 446:         await attachSession(deps, workspace, id, result);
 447:         await warmSession(deps, id);
 448:         result.imported += 1;
 449:         recordSwitchImport(result, portable, id);
 450:         await recordTransfer(deps, key, id, {
 451:             host, at: now, direction: 'pull', events: appended.length, result: 'ok',
 452:         }, result);
 453:         return true;
 454:     }
