 606:  * @param deps - services, settings, filesystem, and git surfaces.
 607:  * @param key - repo workspace key.
 608:  * @param header - the local session header.
 609:  * @param local - the local session's decoded log.
 610:  * @param result - the cycle outcome.
 611:  * @param recordConflict - conflict-path collector.
 612:  * @returns whether the repo artifact was written this cycle.
 613:  */
 614: async function exportSession(deps, key, header, local, result, recordConflict) {
 615:     const localEvents = local.events;
 616:     const repoPath = sessionRepoPath(key, header.id);
 617:     const remoteText = await deps.fs.readRepoFile(repoPath);
 618:     const localText = serializePortableSession(local, key);
 619:     if (remoteText === undefined) {
 620:         await deps.fs.writeRepoFile(repoPath, localText);
 621:         result.pushed += 1;
 622:         return true;
 623:     }
 624:     let remoteEvents;
 625:     try {
 626:         remoteEvents = parsePortableSession(remoteText, key).events;
 627:     }
 628:     catch (error) {
 629:         result.errors.push(`${key}/${String(header.id)}: repo artifact unparsable, overwriting (${messageOf(error)})`);
 630:         remoteEvents = undefined;
 631:     }
 632:     if (remoteEvents === undefined) {
 633:         await deps.fs.writeRepoFile(repoPath, localText);
 634:         result.pushed += 1;
 635:         return true;
 636:     }
 637:     const relation = compareLogs(localEvents, remoteEvents);
 638:     switch (relation) {
 639:         case 'equal':
 640:         case 'local-prefix':
 641:             // The repo already equals or extends local state; nothing to write.
 642:             return false;
 643:         case 'remote-prefix':
 644:             await deps.fs.writeRepoFile(repoPath, localText);
 645:             result.pushed += 1;
 646:             return true;
 647:         case 'divergent': {
 648:             // Never overwrite the repo artifact on divergence: alternating
 649:             // overwrites would destroy the repo's one stable log every cycle, and
 650:             // a divergent local that merely carries the harness's interrupted-turn
 651:             // repair tail would keep replacing the real continuation. Preserve the
 652:             // remote tail as this machine's conflict copy and leave the repo file
 653:             // as it is; the local tail stays on this machine.
 654:             const conflictPath = conflictRepoPath(key, header.id, deps.fs.hostname);
 655:             await deps.fs.writeRepoFile(conflictPath, remoteText);
 656:             recordConflict(conflictPath);
 657:             return false;
 658:         }
 659:     }
 660: }
 661: /**
 662:  * Record this machine's selection edit in the repo. The decision is reported
 663:  * whenever this machine published (that is the user-visible outcome), while
 664:  * the file itself is written only when it would actually differ 鈥?a selection
 665:  * that already matches, including an empty one, needs no commit.
 666:  *
 667:  * Entries this machine already saw keep their original key, workspace name,
 668:  * title, and `addedAt`/`addedBy`: republishing must not restamp another
 669:  * machine's addition. Entries this machine added take the metadata the export
 670:  * pass resolved; an id that could not be described is dropped from the
 671:  * publication with an error rather than published unplaceable.
 672:  * @param deps - services, settings, filesystem, and git surfaces.
 673:  * @param decision - this cycle's selection decision.
 674:  * @param repoEntries - the repo's entries as read, when it had a selection.
 675:  * @param described - workspace placement resolved per exported session.
 676:  * @param result - the cycle outcome.
 677:  * @param nowIso - this cycle's timestamp.
 678:  */
 679: async function publishSelection(deps, decision, repoEntries, described, result, nowIso) {
 680:     if (!decision.publish)
 681:         return;
 682:     const known = new Map((repoEntries ?? []).map(entry => [String(entry.id), entry]));
 683:     const entries = [];
 684:     for (const raw of decision.publishedIds) {
 685:         const existing = known.get(raw);
 686:         if (existing !== undefined) {
 687:             // Republishing another machine's entry must not restamp its provenance.
 688:             entries.push(existing);
 689:             continue;
 690:         }
 691:         const placement = described.get(raw);
 692:         if (placement === undefined) {
 693:             result.errors.push(`selection: cannot publish ${raw} 鈥?this machine cannot describe its workspace`);
 694:             continue;
 695:         }
 696:         entries.push({
 697:             id: SessionId(raw),
 698:             key: placement.key,
 699:             workspaceName: placement.name,
 700:             title: placement.title,
 701:             addedAt: nowIso,
 702:             addedBy: deps.fs.hostname,
 703:         });
 704:     }

