$code=@'
const z=require('node:zlib'), fs=require('node:fs');
const buf=fs.readFileSync(process.argv[2]);
console.log('fileBytes', buf.length, 'magic', buf.subarray(0,4).toString('hex'));
// count zstd frame magic occurrences
let count=0; for (let i=0;i<buf.length-3;i++){ if(buf[i]===0x28&&buf[i+1]===0xb5&&buf[i+2]===0x2f&&buf[i+3]===0xfd) count++; }
console.log('frameMagicCount', count);
const d=z.createZstdDecompress();
const chunks=[];
d.on('data',c=>chunks.push(c));
d.on('error',e=>{console.log('ERR',e.message); process.exit(2);});
d.on('end',()=>{
  const txt=Buffer.concat(chunks).toString('utf8');
  const lines=txt.split('\n').filter(Boolean);
  console.log('decodedChars', txt.length, 'lines', lines.length);
  for (let i=0;i<Math.min(4,lines.length);i++){
    const o=JSON.parse(lines[i]);
    console.log('line'+i,'keys='+Object.keys(o).join(','),'type='+o.type,'seq='+o.seq);
  }
  if(lines.length>1){ const o=JSON.parse(lines[lines.length-1]); console.log('last keys='+Object.keys(o).join(','),'type='+o.type,'seq='+o.seq); }
});
d.end(buf);
'@
