const tmp=process.argv[2];
function parsePortable(text){ const lines=text.split(/\r?\n/).filter(l=>l.length); const header=JSON.parse(lines[0]); const events=lines.slice(1).map(l=>JSON.parse(l)); return {header,events}; }
const A=parsePortable(fs.readFileSync(tmp+'/A.jsonl','utf8'));
const B=parsePortable(fs.readFileSync(tmp+'/B.jsonl','utf8'));
