console.log('C headerKeys=',Object.keys(C.header).join(','),'events=',C.events.length,'sha=',sha(fs.readFileSync(tmp+'/C.jsonl')));
console.log('B==C bytewise?', fs.readFileSync(tmp+'/B.jsonl').equals(fs.readFileSync(tmp+'/C.jsonl')));
console.log('A first5=',A.events.slice(0,5).map(e=>[e.type,e.seq,Object.keys(e).join('+')].join(':')).join(' | '));
console.log('B first5=',B.events.slice(0,5).map(e=>[e.type,e.seq,Object.keys(e).join('+')].join(':')).join(' | '));

const zpath='C:\\Users\\Stupidle\\.dsh\\sessions\\--C-Users-Stupidle-Documents-deepseek-harness-default-workspace--\\session-f97344fe-896f-44c0-818b-668eb4378146\\session.v4.jsonl.zstd';
const buf=fs.readFileSync(zpath);
const pos=[]; for(let i=0;i<buf.length-3;i++){ if(buf[i]===0x28&&buf[i+1]===0xb5&&buf[i+2]===0x2f&&buf[i+3]===0xfd) pos.push(i); }
let out='';
for(let k=0;k<pos.length;k++){ const start=pos[k], end=(k+1<pos.length)?pos[k+1]:buf.length; try{ out+=z.zstdDecompressSync(buf.subarray(start,end)).toString('utf8'); }catch(e){ console.log('frameErr',k,e.message); } }
const L=parsePortable(out);
console.log('local headerKeys=',Object.keys(L.header).join(','),'events=',L.events.length);
console.log('L first5=',L.events.slice(0,5).map(e=>[e.type,e.seq,Object.keys(e).join('+')].join(':')).join(' | '));
console.log('L types/seqs=', L.events.map((e,i)=>i+':'+e.type+'#'+e.seq).join(' '));

function canon(v){
  if(Array.isArray(v)) return '['+v.map(canon).join(',')+']';
  if(v&&typeof v==='object') return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canon(v[k])).join(',')+'}';
  return JSON.stringify(v);
}
function firstDiff(a,b,path='',acc=[]){
  if(acc.length>=10) return acc;
  if(a===b) return acc;
  const ta=a===null?'null':Array.isArray(a)?'array':typeof a;
  const tb=b===null?'null':Array.isArray(b)?'array':typeof b;
  if(ta!==tb){ acc.push(path+':type('+ta+'->'+tb+')'); return acc; }
  if(ta==='array'){ if(a.length!==b.length) acc.push(path+':length('+a.length+'->'+b.length+')'); for(let i=0;i<Math.min(a.length,b.length);i++) firstDiff(a[i],b[i],path+'['+i+']',acc); return acc; }
  if(ta==='object'){ const ka=Object.keys(a),kb=Object.keys(b); for(const k of ka) if(!(k in b)) acc.push(path+'.'+k+':missing-in-B'); for(const k of kb) if(!(k in a)) acc.push(path+'.'+k+':missing-in-A'); for(const k of ka) if(k in b) firstDiff(a[k],b[k],path+'.'+k,acc); return acc; }
  acc.push(path+':value'); return acc;
}
function cmp(label,X,Y){
  const n=Math.min(X.length,Y.length); let first=-1, firstCanon=-1;
  for(let i=0;i<n;i++){ if(JSON.stringify(X[i])!==JSON.stringify(Y[i])){ first=i; break; } }
  for(let i=0;i<n;i++){ if(canon(X[i])!==canon(Y[i])){ firstCanon=i; break; } }
  console.log(`--- ${label}: lengths ${X.length} vs ${Y.length}; firstRawDiff=${first}; firstCanonDiff=${firstCanon}`);
  if(first>=0){ const e=X[first],f=Y[first]; console.log('  at index',first,'type',e.type,'/',f.type,'seq',e.seq,'/',f.seq); console.log('  keyOrderA=',Object.keys(e).join(',')); console.log('  keyOrderB=',Object.keys(f).join(',')); console.log('  rawDiffPaths=',JSON.stringify(firstDiff(e,f))); }
  if(firstCanon>=0 && firstCanon!==first){ const e=X[firstCanon],f=Y[firstCanon]; console.log('  CANON-only diff at index',firstCanon,'type',e.type,'seq',e.seq,'paths=',JSON.stringify(firstDiff(e,f))); }
}
cmp('A vs B[0..A.len)', A.events, B.events.slice(0,A.events.length));
cmp('local vs A', L.events, A.events);
cmp('local vs B', L.events, B.events);
'@
$b=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($script))
node -e "eval(Buffer.from(process.argv[1],'base64').toString())" $b $tmp", "description": "Compare git versions and local session structurally"}

