```
/** Whether two decoded events carry identical content at one seq. */
function canonicalJson(value) {
    if (Array.isArray(value))
        return `[${value.map(canonicalJson).join(',')}]`;
    if (value !== null && typeof value === 'object') {
        return `{${Object.keys(value).sort()
            .map(key => `${JSON.stringify(key)}:${canonicalJson(value[key])}`)
            .join(',')}}`;
    }
    return JSON.stringify(value);
}
/** Comparison form of one event: the resume marker's time is machine-local. */
function comparableEvent(event) {
    if (event.type !== 'session/end-seed')
        return event;
    const { time, ...rest } = event;
    return rest;
}
function sameEvent(left, right) {
    return canonicalJson(comparableEvent(left)) === canonicalJson(comparableEvent(right));
}
```
Need avoid unused `time` lint? No lint running. Use `const { time: _time, ...rest }`. Fine.

